// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Bank bank;

    function setUp() public {
        c = new ModifierEntrancy();
        bank = new Bank();
    }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max);
        address actor = address(bank);
        bool ok;
        vm.prank(actor);
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.tokenBalance(actor) == 20);
    }
}
